def gap(c, p, S, K, r, T):
    """Call side minus put side of parity."""
    return c + K / (1 + r) ** T - (p + S)

def arbitrage(c, p, S, K, r, T, cost=0.0):
    """Riskless profit per call-put pair today, after cost; 0.0 if none."""
    return max(abs(gap(c, p, S, K, r, T)) - cost, 0.0)

def trade(c, p, S, K, r, T, cost=0.0):
    """Which side to sell: 'call side', 'put side' or 'none'."""
    if arbitrage(c, p, S, K, r, T, cost) == 0.0:
        return 'none'
    return 'call side' if gap(c, p, S, K, r, T) > 0 else 'put side'
